    d = start + timedelta(days=1)
    c = 1
    while c < n:
        d += timedelta(days=1); c += 1
    while d.weekday() >= 5 or d in fed_hol:
        d += timedelta(days=1)
    return d

def forward(d, n):  # subtract-style: n days BEFORE a due date (26(f))
    return d - timedelta(days=n)

